module MinMexOptimizer (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [3:0] n,\n    input wire [3:0] m,\n    input wire valid_in,\n    input wire [3:0] l_in,\n    input wire [3:0] r_in,\n    output reg [4:0] min_length,\n    output reg [63:0] result_array,\n    output reg done\n);\n    localparam [1:0] IDLE = 2'b00;\n    localparam [1:0] PROCESS = 2'b01;\n    localparam [1:0] GENERATE = 2'b10;\n    \n    reg [1:0] state;\n    reg [3:0] query_count;\n    reg [4:0] current_min;\n    reg [4:0] length;\n    integer i;\n    \n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            min_length <= 5'd0;\n            result_array <= 64'd0;\n            query_count <= 4'd0;\n            current_min <= 5'b11111;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        query_count <= 4'd0;\n                        current_min <= 5'b11111;\n                        state <= PROCESS;\n                    end\n                end\n                \n                PROCESS: begin\n                    if (valid_in && (query_count < m)) begin\n                        length <= (r_in - l_in) + 4'd1;\n                        if (length < current_min)\n                            current_min <= length;\n                        query_count <= query_count + 4'd1;\n                    end\n                    if (query_count == m)\n                        state <= GENERATE;\n                end\n                \n                GENERATE: begin\n                    // Generate result array elements\n                    for (i = 0; i < 16; i = i + 1) begin\n                        if (i < n) begin\n                            if (current_min != 5'd0)\n                                result_array[i*4 +:4] <= i % current_min;\n                            else\n                                result_array[i*4 +:4] <= 4'b0;\n                        end else begin\n                            result_array[i*4 +:4] <= 4'b0;\n                        end\n                    end\n                    min_length <= current_min;\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule